53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    private final OwnerFieldsValidator ownerFieldsValidator;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper,
73	                                 OwnerFieldsValidator ownerFieldsValidator) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	        this.ownerFieldsValidator = ownerFieldsValidator;
79	    }
80	
81	    @InitBinder("ownerFieldsDto")
82	    void initOwnerFieldsBinder(WebDataBinder binder) {
83	        binder.addValidators(ownerFieldsValidator);
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        HttpHeaders headers = new HttpHeaders();
115	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
116	        this.clinicService.saveOwner(owner);
117	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
118	        headers.setLocation(UriComponentsBuilder.newInstance()
119	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
120	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
126	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
127	        if (currentOwner == null) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        currentOwner.setAddress(ownerFieldsDto.getAddress());
131	        currentOwner.setCity(ownerFieldsDto.getCity());
132	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
133	        currentOwner.setLastName(ownerFieldsDto.getLastName());
134	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
135	        this.clinicService.saveOwner(currentOwner);
136	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Transactional
141	    @Override
142	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
143	        Owner owner = this.clinicService.findOwnerById(ownerId);
144	        if (owner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        this.clinicService.deleteOwner(owner);
148	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
154	        Owner owner = this.clinicService.findOwnerById(ownerId);
155	        if (owner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        HttpHeaders headers = new HttpHeaders();
159	        Pet pet = petMapper.toPet(petFieldsDto);
160	        owner.setId(ownerId);
161	        pet.setOwner(owner);
162	        pet.getType().setName(null);
163	        this.clinicService.savePet(pet);
164	        PetDto petDto = petMapper.toPetDto(pet);
165	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
166	            .buildAndExpand(pet.getId()).toUri());
167	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
173	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
174	        if (currentOwner != null) {
175	            Pet currentPet = this.clinicService.findPetById(petId);
176	            if (currentPet != null) {
177	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
178	                currentPet.setName(petFieldsDto.getName());
179	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
180	                this.clinicService.savePet(currentPet);
181	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
182	            }
183	        }
184	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
190	        HttpHeaders headers = new HttpHeaders();
191	        Visit visit = visitMapper.toVisit(visitFieldsDto);
192	        Pet pet = new Pet();
193	        pet.setId(petId);
194	        visit.setPet(pet);
195	        this.clinicService.saveVisit(visit);
196	        VisitDto visitDto = visitMapper.toVisitDto(visit);
197	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
198	            .buildAndExpand(visit.getId()).toUri());
199	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
200	    }
201	
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
206	        Owner owner = this.clinicService.findOwnerById(ownerId);
207	        if (owner != null) {
208	            Pet pet = owner.getPet(petId);
209	            if (pet != null) {
210	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
211	            }
212	        }
213	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
214	    }
215	}
