22	import org.springframework.validation.ValidationUtils;
23	import org.springframework.validation.Validator;
24	
25	/**
26	 * Rejects an {@link OwnerFieldsDto} whose required text fields are missing or blank.
27	 * <p>
28	 * Registered on the owner controller through {@code @InitBinder} so it runs as part of the
29	 * standard {@code @Valid} pass on the request body: every rejected field is recorded as a
30	 * field error on the shared {@link Errors}, surfacing through the usual bad-request handling.
31	 *
32	 * @author Vitaliy Fedoriv
33	 */
34	@Component
35	public class OwnerFieldsValidator implements Validator {
36	
37	    private static final String[] REQUIRED_FIELDS = {"firstName", "lastName", "address", "city", "telephone"};
38	
39	    @Override
40	    public boolean supports(Class<?> clazz) {
41	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
42	    }
43	
44	    @Override
45	    public void validate(Object target, Errors errors) {
46	        for (String field : REQUIRED_FIELDS) {
47	            ValidationUtils.rejectIfEmptyOrWhitespace(errors, field, "required", "must not be blank");
48	        }
49	    }
50	}
